mapper.select:
SELECT id, user_id, balance, status, last_update_time, create_time
FROM wallets
WHERE user_id = #{userId}

SELECT id, user_id, balance, status, last_update_time, create_time
FROM wallets
WHERE id = #{id}

mapper.update:
UPDATE wallets
SET balance = balance + #{amount}, last_update_time = NOW()
WHERE id = #{id}

UPDATE wallets
SET status = #{status}, last_update_time = NOW()
WHERE id = #{id}
